/**
 * Fails when a file in docs/media is one no rendered page shows.
 *
 *   node scripts/check-media-refs.mjs
 *
 * The figures are committed, so the opposite direction — a doc naming a figure
 * that does not exist — shows up as a broken image the deploy's link check
 * catches. Nothing watched this direction, and it went wrong quietly: eight
 * PNGs sat in docs/media for months, regenerated by `pnpm screenshots:all` on
 * every run, after the pages that showed them stopped showing them. Four had
 * lost their page; three were captures the gallery replaced with text links;
 * one, example-nucleotide.svg, was never shown anywhere at all.
 *
 * The trap this exists to avoid is subtle enough that a hand audit fell into it
 * twice: a file that MAKES a figure is not a file that SHOWS one.
 * generateFigures.tsx names every SVG it writes, and specs.mjs names every PNG
 * it captures, so grepping the whole repo for a basename answers "yes, someone
 * mentions it" for a figure nobody renders. Only CONSUMERS count here, and
 * GENERATORS are excluded by path.
 *
 * A consumer is markdown that embeds the file, a website page or component that
 * names it, or a source file that reads it at build time. Naming a figure in a
 * comment counts: a comment is how the repo records that a figure is the
 * og:image or the subject of a doc, and a figure referenced only in prose is
 * still a figure someone decided to keep.
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const repoRoot = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '..',
)
const mediaDir = path.join(repoRoot, 'docs', 'media')

// Where a figure can be shown. Directories, walked recursively.
const CONSUMER_DIRS = [
  'docs',
  'website/src',
  'packages',
  'README.md',
  'USAGE.md',
]

// Where figures are MADE. A mention inside one of these is the generator naming
// its own output, which is not evidence that any page shows it.
const GENERATOR_PATHS = [
  'scripts',
  'packages/lib/scripts/generateFigures.tsx',
  'packages/python/scripts',
]

const CONSUMER_EXT = new Set([
  '.md',
  '.astro',
  '.ts',
  '.tsx',
  '.mjs',
  '.js',
  '.json',
  '.R',
  '.Rmd',
  '.py',
])

const SKIP_DIRS = new Set(['node_modules', 'dist', '.astro', 'media', 'data'])

function walk(rel, out) {
  const abs = path.join(repoRoot, rel)
  if (!fs.existsSync(abs)) {
    return out
  }
  if (fs.statSync(abs).isFile()) {
    out.push(rel)
    return out
  }
  for (const entry of fs.readdirSync(abs, { withFileTypes: true })) {
    if (entry.isDirectory()) {
      if (!SKIP_DIRS.has(entry.name)) {
        walk(path.join(rel, entry.name), out)
      }
    } else if (CONSUMER_EXT.has(path.extname(entry.name))) {
      out.push(path.join(rel, entry.name))
    }
  }
  return out
}

const isGenerator = rel =>
  GENERATOR_PATHS.some(g => rel === g || rel.startsWith(`${g}/`))

const consumers = CONSUMER_DIRS.flatMap(dir => walk(dir, [])).filter(
  rel => !isGenerator(rel),
)

const haystack = consumers.map(rel => ({
  rel,
  text: fs.readFileSync(path.join(repoRoot, rel), 'utf8'),
}))

const orphans = []
for (const file of fs.readdirSync(mediaDir).sort()) {
  const stem = file.replace(/\.[^.]+$/, '')
  // Match the stem as a whole token, so `domain-loss` is not counted as shown
  // by a page that only names `domain-loss-closeup`.
  const re = new RegExp(`\\b${stem.replaceAll('-', '\\-')}\\b(?!-)`)
  if (!haystack.some(h => re.test(h.text))) {
    orphans.push(file)
  }
}

if (orphans.length > 0) {
  console.error(
    `docs/media holds ${orphans.length} file(s) no page shows:\n` +
      orphans.map(f => `  ${f}`).join('\n') +
      '\n\nEither show it somewhere, or delete it together with the spec that ' +
      'makes it\n(scripts/screenshots/specs.mjs, or ' +
      'packages/lib/scripts/generateFigures.tsx) so nothing\nregenerates it.',
  )
  process.exit(1)
}

console.log(
  `docs/media: ${fs.readdirSync(mediaDir).length} files, all shown by a page`,
)
